<script setup lang="ts">
import {ref,watch,onUnmounted} from 'vue'
import type {StorageApi} from '../api'
import type {Product,ReceiptLine,Category} from '../types'
import {useMerchantStorageText} from './text'
const props=defineProps<{api:StorageApi;line:ReceiptLine;categories:Category[];disabled:boolean;code?:string;canCreateCategory?:boolean}>()
const emit=defineEmits<{choose:[Product];clear:[];manual:[];patch:[Partial<ReceiptLine>];error:[unknown];busy:[boolean];editing:[boolean];createCategory:[]}>(),{t,locale}=useMerchantStorageText()
const query=ref(''),category=ref(''),appliedQuery=ref(''),appliedCategory=ref(''),page=ref(0),hasMore=ref(false),results=ref<Product[]>([]),loading=ref(false),failed=ref(false),mode=ref<'existing'|'manual'>(!props.line.productId&&(props.line.nameZh||props.line.nameEn)?'manual':'existing'),editing=ref(!props.line.productId)
const categoryInput=crypto.randomUUID()
let generation=0
function resetSearch(){generation++;loading.value=false;emit('busy',false);query.value='';category.value='';appliedQuery.value='';appliedCategory.value='';page.value=0;hasMore.value=false;results.value=[];failed.value=false}
async function loadPage(){const own=++generation;loading.value=true;emit('busy',true);failed.value=false;results.value=[];hasMore.value=false;try{const params=new URLSearchParams({query:appliedQuery.value,page:String(page.value),size:'6'});if(appliedCategory.value)params.set('categoryId',appliedCategory.value);const found=await props.api.get<{items:Product[];hasMore:boolean}>('/product-options?'+params);if(own===generation){results.value=found.items??[];hasMore.value=found.hasMore===true}}catch(e){if(own===generation){failed.value=true;emit('error',e)}}finally{if(own===generation){loading.value=false;emit('busy',false)}}}
function search(){appliedQuery.value=query.value.trim();appliedCategory.value=category.value;page.value=0;void loadPage()}
function turnPage(offset:number){if(props.disabled||loading.value||failed.value||offset<0&&!page.value||offset>0&&!hasMore.value)return;page.value+=offset;void loadPage()}
function filterCategory(value:string){category.value=value;search()}
function setMode(value:'existing'|'manual'){if(value===mode.value)return;const name=query.value.trim();resetSearch();mode.value=value;editing.value=true;emit('manual');if(value==='existing')void search();else if(name)emit('patch',locale.value.startsWith('en')?{nameEn:name}:{nameZh:name})}
function select(product:Product){resetSearch();emit('choose',product);editing.value=false}
function clear(){resetSearch();mode.value='existing';editing.value=true;emit('clear');void search()}
function reselect(){editing.value=true;mode.value='existing';void search()}
watch([editing,()=>props.line.productId],()=>emit('editing',!!props.line.productId&&editing.value),{immediate:true})
watch(()=>props.line.productId,id=>{if(id){editing.value=false;mode.value='existing'}})
watch(()=>props.api.base,()=>{resetSearch();if(editing.value&&mode.value==='existing')void search()},{immediate:true})
onUnmounted(()=>{generation++;emit('busy',false);emit('editing',false)})
</script>
<template><section class="storage-receipt-wine-picker">
 <div v-if="line.productId&&!editing" class="storage-selected-wine"><div><small>{{t('selectedWine')}}</small><strong>{{locale.startsWith('en')?line.nameEn||line.nameZh:line.nameZh||line.nameEn}}</strong><small v-if="code">{{code}}</small></div><div class="storage-inline"><button type="button" :disabled="disabled" @click="reselect">{{t('reselectWine')}}</button><button type="button" :disabled="disabled" @click="clear">{{t('clearWine')}}</button></div></div>
 <template v-else>
  <div class="storage-wine-modes" :aria-label="t('chooseWineStep')"><button type="button" :aria-pressed="mode==='existing'" :class="{primary:mode==='existing'}" :disabled="disabled" @click="setMode('existing')">{{t('existingWineTab')}}</button><button type="button" :aria-pressed="mode==='manual'" :class="{primary:mode==='manual'}" :disabled="disabled" @click="setMode('manual')">＋ {{t('newWineTab')}}</button><button type="button" :disabled="disabled" @click="clear">{{t('clearWine')}}</button><button v-if="line.productId" type="button" :disabled="disabled" @click="editing=false">{{t('keepWine')}}</button></div>
  <template v-if="mode==='existing'"><div class="storage-receive-search-row"><label>{{t('wineSearch')}}<input v-model="query" maxlength="120" :placeholder="t('wineSearchHint')" :disabled="disabled" @keydown.enter.prevent="search"></label><button type="button" :disabled="disabled||loading" @click="search">{{t(loading?'loading':'searchWine')}}</button><button v-if="query||category" type="button" :disabled="disabled" @click="resetSearch();search()">{{t('clearSearch')}}</button></div>
   <label>{{t('category')}}<select data-testid="wine-category-filter" :value="category" :disabled="disabled||loading" @change="filterCategory(($event.target as HTMLSelectElement).value)"><option value="">{{t('allCategories')}}</option><option v-for="c in categories" :key="c.id" :value="c.id">{{locale.startsWith('en')?c.nameEn||c.nameZh:c.nameZh||c.nameEn}}</option></select></label>
   <p v-if="loading" role="status">{{t('loadingWine')}}</p><p v-else-if="failed" role="alert">{{t('wineSearchFailed')}}</p><template v-else><p class="cards-muted">{{t(results.length?'pickWineResult':'noWineResults')}}</p><div class="storage-wine-result-list"><button v-for="product in results" :key="product.id" type="button" :disabled="disabled" @click="select(product)"><span><strong>{{locale.startsWith('en')?product.nameEn||product.nameZh:product.nameZh||product.nameEn}}</strong><small>{{product.code}}</small></span><span>{{t('selectWineResult')}}</span></button></div><div v-if="page||hasMore" class="storage-inline storage-wine-pagination"><button type="button" :disabled="disabled||loading||!page" @click="turnPage(-1)">{{t('previousPage')}}</button><span>{{t('pageLabel')}} {{page+1}}</span><button type="button" :disabled="disabled||loading||!hasMore" @click="turnPage(1)">{{t('nextPage')}}</button></div></template>
  </template>
  <template v-else><p class="cards-muted">{{t('manualWineNames')}}</p><div class="storage-receive-grid"><label>{{t('nameZh')}}<input :value="line.nameZh" maxlength="200" :disabled="disabled" @input="emit('patch',{nameZh:($event.target as HTMLInputElement).value})"></label><label>{{t('nameEn')}}<input :value="line.nameEn" maxlength="200" :disabled="disabled" @input="emit('patch',{nameEn:($event.target as HTMLInputElement).value})"></label></div><div class="storage-inline"><label :for="'receipt-category-'+categoryInput">{{t('optionalWineCategory')}}</label><button v-if="canCreateCategory" type="button" :disabled="disabled" @click="emit('createCategory')">{{locale.startsWith('en')?'＋ Add category':'＋ 新增分类'}}</button></div><select :id="'receipt-category-'+categoryInput" :value="line.categoryId" :disabled="disabled" @change="emit('patch',{categoryId:($event.target as HTMLSelectElement).value})"><option value="">{{t('noWineCategory')}}</option><option v-for="category in categories.filter(c=>!c.uncategorized)" :key="category.id" :value="category.id">{{category.nameZh||category.nameEn}}</option></select></template>
 </template>
</section></template>
